[ExtensionOf(TableStr(CustInvoiceTrans))]
final class METCustInvoiceTransTable_Extension
{
}

Method.Source:
    /// <summary>
    /// Extension of init from Sales line
    /// </summary>
    /// <param name = "salesLine">Sales line</param>
    /// <param name = "_salesParmLine">Sales parm line</param>
    void initFromSalesLine(SalesLine salesLine, SalesParmLine _salesParmLine)
    {
        next initFromSalesLine(salesLine, _salesParmLine);

        this.METCase        = salesLine.metInvoicedTotalcases(this.Qty);//CB272 displayMETcases();
        this.METGrossWeight = salesLine.displayMETInvoicedGrossWeight(this.Qty);//CB272
        if(salesLine.SalesUnit != "litres")
        {
            //this.METLitres =  any2Str((UnitOfMeasureConverter::convert(UnitOfMeasureConverter::convert(UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No),
            //                                UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('litres'), NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No));

            //UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(_custInvoiceTrans.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), NoYes::No, InventTable::itemProduct(_custInvoiceTrans.ItemId), NoYes::No);
            //todo                  
            //this.METLitres =  any2Str((UnitOfMeasureConverter::convert(UnitOfMeasureConverter::convert(1, UnitOfMeasure::unitOfMeasureIdBySymbol(salesLine.SalesUnit), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), NoYes::No, InventTable::itemProduct(salesLine.ItemId), NoYes::No))), UnitOfMeasure::unitOfMeasureIdBySymbol('ea'), UnitOfMeasure::unitOfMeasureIdBySymbol('litres'), NoYes::No, InventTable::itemProduct(salesLine.ItemId), NoYes::No));
        }
        else
        {
            this.METLitres =  salesLine.SalesUnit;
        }//todo
        
        this.METItemType =   salesLine.displayMETItemType();
        this.METFreeItemExciseVendClaimStatus = salesLine.LineAmount==0? METFreeItemExciseVendClaimStatus::Pending : METFreeItemExciseVendClaimStatus::NotRequired;
    }

/// <summary>
/// Get Metcash item type for item on the SalesLine.
/// </summary>
/// <returns>Metcash item type</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METItemTypes displayMETItemType()
{
    return InventTable::metGetItemType(this.ItemId, this.inventDim().InventSiteId);
}

/// <summary>
/// Get Metcash item type for item on the SalesLine.
/// </summary>
/// <returns>Metcash item type</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METItemTypes displayMETUOMLitres()
{
    return InventTable::metGetItemType(this.ItemId, this.inventDim().InventSiteId);
}
